local function unpack85(s,n)
 local chunks={};local q=1
 for i=1,#s,5 do
  local v=0
  for j=i,i+4 do v=v*85+(s:byte(j)-33) end
  chunks[q]=string.char(math.floor(v/16777216)%256,math.floor(v/65536)%256,math.floor(v/256)%256,v%256)
  q=q+1
 end
 local x=table.concat(chunks)
 return x:sub(1,n)
end
local function inflate(s)
 local idx,hold,nb=1,0,0
 local function bits(n)
  while nb<n do local a=s:byte(idx);if not a then error("Unexpected end of compressed script") end;hold=hold+a*2^nb;nb=nb+8;idx=idx+1 end
  local x=hold%2^n;hold=math.floor(hold/2^n);nb=nb-n;return x
 end
 local function tree(lens)
  local counts,nexts,tbl={},{},{};local max=0
  for i=1,#lens do local len=lens[i];if len>0 then counts[len]=(counts[len] or 0)+1;if len>max then max=len end end end
  local code=0
  for k=1,max do code=(code+(counts[k-1] or 0))*2;nexts[k]=code;tbl[k]={} end
  for i=1,#lens do local len=lens[i];if len>0 then local c=nexts[len];nexts[len]=c+1;tbl[len][c]=i-1 end end
  return {nodes=tbl,max=max}
 end
