      elseif x==17 then copies=bits(3)+3;value=0
      else copies=bits(7)+11;value=0 end
      for j=1,copies do lengths[#lengths+1]=value end
     end
    end
    local a,d={},{}
    for j=1,hlit do a[j]=lengths[j] end
    for j=1,hdist do d[j]=lengths[hlit+j] end
